CREATE POLICY "own portrait read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'avatar-portraits' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own portrait insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatar-portraits' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own portrait update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'avatar-portraits' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'avatar-portraits' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "own portrait delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'avatar-portraits' AND (storage.foldername(name))[1] = auth.uid()::text);